nique // secure token to fetch without logging in\n  cancelledAt        DateTime?\n  cancellationReason String?\n  deliveredAt        DateTime?\n  createdAt          DateTime    @default(now())\n  updatedAt          DateTime    @updatedAt\n  items              OrderItem[]\n  payment            Payment?\n\n  @@index([businessDate])\n  @@index([customerPhone])\n  @@index([publicOrderId])\n}\n\nmodel OrderItem {\n  id         String    @id @default(uuid())\n  orderId    String\n  order      Order     @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  menuItemId String?\n  menuItem   MenuItem? @relation(fields: [menuItemId], references: [id], onDelete: SetNull)\n  name       String // snapshot at purchase time\n  unitPrice  Float // snapshot at purchase time\n  quantity   Int\n  subtotal   Float\n}\n\nmodel Payment {\n  id               String   @id @default(uuid())\n  orderId          String   @unique\n  order            Order    @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  gateway          String // e.g. \"RAZORPAY\"\n  gatewayOrderId   String   @unique\n  gatewayPaymentId String?  @unique\n  amount           Float\n  currency         String   @default(\"INR\")\n  status           String // PENDING, PAID, FAILED\n  signature        String?\n  createdAt        DateTime @default(now())\n  updatedAt        DateTime @updatedAt\n}\n\nmodel ShopState {\n  id                 String   @id @default(uuid())\n  businessDate       String   @unique // Format: YYYY-MM-DD\n  manualClosed       Boolean  @default(false)\n  openingTime        String   @default(\"08:00\") // Format: HH:MM\n  closingTime        String   @default(\"11:00\") // Format: HH:MM\n  cancellationCutoff String   @default(\"11:00\") // Format: HH:MM\n  createdAt          DateTime @default(now())\n  updatedAt          DateTime @updatedAt\n}\n",
